import java.io.PrintWriter;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int n = in.nextInt();
        if (n > 40) {
            out.println(0);
            out.close();
            return;
        }

        ArrayList<Point> points = new ArrayList<>();
        for (int i = 0; i < n; ++i) {
            points.add(new Point(in.nextInt(), in.nextInt(), in.nextInt(), in.nextInt(), in.nextInt()));
        }

        if (n < 3) {
            out.println(n);
            for (int i = 1; i <= n; ++i) out.println(i);
            out.close();
            return;
        }

        ArrayList<Integer> result = new ArrayList<>();
        for (int centerIdx = 0; centerIdx < n; ++centerIdx) {
            Point center = points.get(centerIdx);
            ArrayList<Vector> vectors = new ArrayList<>();

            for (int i = 0; i < n; ++i) {
                if (i == centerIdx) continue;
                Point p = points.get(i);
                vectors.add(new Vector(
                        p.a - center.a,
                        p.b - center.b,
                        p.c - center.c,
                        p.d - center.d,
                        p.e - center.e
                ));
            }

            boolean bad = false;
            check:
            for (int i = 0; i < vectors.size(); ++i) {
                for (int j = i + 1; j < vectors.size(); ++j) {
                    if (vectors.get(i).dot(vectors.get(j)) > 0) {
                        bad = true;
                        break check;
                    }
                }
            }

            if (!bad) result.add(centerIdx + 1);
        }

        out.println(result.size());
        for (int id : result) out.println(id);
        out.close();
    }

    static class Point {
        long a, b, c, d, e;

        Point(long a, long b, long c, long d, long e) {
            this.a = a;
            this.b = b;
            this.c = c;
            this.d = d;
            this.e = e;
        }
    }

    static class Vector {
        long a, b, c, d, e;

        Vector(long a, long b, long c, long d, long e) {
            this.a = a;
            this.b = b;
            this.c = c;
            this.d = d;
            this.e = e;
        }

        long dot(Vector other) {
            return a * other.a + b * other.b + c * other.c + d * other.d + e * other.e;
        }
    }
}
